function nav(route) { location.hash = route; go(route); }
function dateText(value) { if (!value) return "—"; const date = new Date(`${value}T00:00:00`); return Number.isNaN(date.valueOf()) ? "—" : new Intl.DateTimeFormat(state.lang === "kn" ? "kn-IN" : "en-IN", { day: "numeric", month: "short", year: "numeric" }).format(date); }
