async function loadDashboard() {
  const [counters, schemes] = await Promise.all([
    api("/rest/v1/usage_counters?select=*&order=class_level.asc"),
    api("/rest/v1/schemes?select=id,name_en,type,deadline,last_verified,status&order=deadline.asc.nullslast", {}, true)
  ]);
  state.dashboard = { counters: counters || [], schemes: schemes || [] };
}
function dashboardContent() {
  if (!state.dashboard) return `<p class="quiet-line">${esc(t("serverUnavailable"))}</p>`;
  const rows = state.dashboard.counters; const checks = rows.reduce((sum, row) => sum + row.checks, 0); const zeros = rows.reduce((sum, row) => sum + row.zero_results, 0); const byClass = Array.from({ length: 12 }, (_, i) => rows.filter(r => r.class_level === i + 1).reduce((sum, row) => sum + row.checks, 0)); const byCategory = categoryValues.map(category => ({ category, count: rows.filter(r => r.category === category).reduce((sum, row) => sum + row.zero_results, 0) }));
  const today = new Date(); const soon = new Date(today); soon.setDate(soon.getDate() + 30); const stale = state.dashboard.schemes.filter(row => row.status === "Published" && (!row.last_verified || new Date(`${row.last_verified}T00:00:00`) < new Date(today.valueOf() - 90 * 86400000))); const deadlines = state.dashboard.schemes.filter(row => row.status === "Published" && row.deadline && new Date(`${row.deadline}T00:00:00`) >= today && new Date(`${row.deadline}T00:00:00`) <= soon);
  return `<div class="stats-grid"><article class="stat-box"><span>${esc(t("totalChecks"))}</span><strong>${numberText(checks)}</strong></article><article class="stat-box"><span>${esc(t("zeroRate"))}</span><strong>${checks ? `${Math.round(zeros / checks * 100)}%` : "0%"}</strong></article><article class="stat-box"><span>${esc(t("stale"))}</span><strong>${numberText(stale.length)}</strong></article><article class="stat-box"><span>${esc(t("upcoming"))}</span><strong>${numberText(deadlines.length)}</strong></article></div><div class="dashboard-grid"><section class="staff-section"><h2>${esc(t("byClass"))}</h2>${checks ? `<div class="bar-chart">${byClass.map((count, i) => `<div class="bar-item"><span>${i + 1}</span><div><i style="width:${count ? Math.max(4, count / Math.max(...byClass) * 100) : 0}%"></i></div><b>${numberText(count)}</b></div>`).join("")}</div>` : `<p>${esc(t("noData"))}</p>`}</section><section class="staff-section"><h2>${esc(t("byCategory"))}</h2>${checks ? `<ul class="plain-list">${byCategory.map(item => `<li><span>${esc(categoryLabel(item.category))}</span><strong>${numberText(item.count)}</strong></li>`).join("")}</ul>` : `<p>${esc(t("noData"))}</p>`}</section><section class="staff-section"><h2>${esc(t("stale"))}</h2>${schemeListCompact(stale)}</section><section class="staff-section"><h2>${esc(t("upcoming"))}</h2>${schemeListCompact(deadlines, true)}</section></div>`;
}
function categoryLabel(value) { const i = categoryValues.indexOf(value); return i >= 0 ? t("categories")[i] : value; }
function schemeListCompact(rows, deadline = false) { return rows.length ? `<ul class="plain-list">${rows.map(row => `<li><span>${esc(localized(row, "name") || row.name_en)}</span><strong>${esc(dateText(deadline ? row.deadline : row.last_verified))}</strong></li>`).join("")}</ul>` : `<p>${esc(t("noSchemes"))}</p>`; }

async function loadSchemes() { state.schemes = await api("/rest/v1/schemes?select=*&order=updated_at.desc", {}, true) || []; }
function schemeListPage() {
  const rows = state.schemes.filter(row => `${row.name_en} ${row.name_kn} ${row.status}`.toLowerCase().includes(state.search.toLowerCase()));
  return `<div class="staff-toolbar"><label class="search-field"><span aria-hidden="true">⌕</span><input aria-label="${esc(t("search"))}" placeholder="${esc(t("search"))}" value="${esc(state.search)}" oninput="searchSchemes(this.value)"></label><button class="button button-primary" onclick="editScheme()">＋ ${esc(t("addScheme"))}</button></div>${rows.length ? `<div class="table-wrap"><table class="data-table"><thead><tr><th>${esc(t("schemeNameEn"))}</th><th>${esc(t("type"))}</th><th>${esc(t("status"))}</th><th>${esc(t("verified"))}</th><th></th></tr></thead><tbody>${rows.map(row => `<tr><td><strong>${esc(localized(row, "name"))}</strong><small>${esc(row.data_source?.startsWith("SAMPLE DATA") ? t("sampleBadge") : "")}</small></td><td>${esc(t(row.type === "Private" ? "private" : "government"))}</td><td><span class="status status-${row.status.toLowerCase()}">${esc(t(row.status.toLowerCase()))}</span></td><td>${esc(dateText(row.last_verified))}</td><td><button class="text-arrow" onclick="editScheme('${esc(row.id)}')">${esc(t("edit"))} →</button></td></tr>`).join("")}</tbody></table></div>` : `<p class="quiet-line">${esc(t("noSchemes"))}</p>`}<div id="scheme-editor"></div>`;
}
function editScheme(id = "") {
  const row = state.schemes.find(item => item.id === id) || {};
  const selected = row.categories || [];
  const panel = document.querySelector("#scheme-editor");
  if (!panel) return;
  panel.innerHTML = `<form class="scheme-form" onsubmit="saveScheme(event,'${esc(id)}')"><div class="form-heading"><h2>${esc(id ? t("edit") : t("addScheme"))}</h2><button type="button" class="icon-button" aria-label="${esc(t("close"))}" onclick="this.closest('form').remove()">×</button></div><div class="form-grid"><label>${esc(t("schemeNameEn"))}<input name="name_en" required value="${esc(row.name_en || "")}"></label><label>${esc(t("schemeNameKn"))}<input name="name_kn" required value="${esc(row.name_kn || "")}"></label><label>${esc(t("type"))}<select name="type"><option value="Government" ${row.type !== "Private" ? "selected" : ""}>${esc(t("government"))}</option><option value="Private" ${row.type === "Private" ? "selected" : ""}>${esc(t("private"))}</option></select></label><label>${esc(t("status"))}<select name="status">${["Draft", "Published", "Hidden"].map(value => `<option ${row.status === value ? "selected" : ""}>${esc(t(value.toLowerCase()))}</option>`).join("")}</select></label><label>${esc(t("classMin"))}<select name="class_min">${classValues.map(value => `<option value="${value}" ${Number(row.class_min || 1) === value ? "selected" : ""}>${value}</option>`).join("")}</select></label><label>${esc(t("classMax"))}<select name="class_max">${classValues.map(value => `<option value="${value}" ${Number(row.class_max || 12) === value ? "selected" : ""}>${value}</option>`).join("")}</select></label><fieldset class="category-field"><legend>${esc(t("allowedCategories"))}</legend>${categoryValues.map((value, i) => `<label class="check-option"><input type="checkbox" name="categories" value="${value}" ${selected.includes(value) ? "checked" : ""}>${esc(t("categories")[i])}</label>`).join("")}</fieldset><label>${esc(t("genderRestriction"))}<select name="gender_restriction">${[["any", t("any")], ["female", t("genders")[0]], ["male", t("genders")[1]]].map(([value, label]) => `<option value="${value}" ${row.gender_restriction === value ? "selected" : ""}>${esc(label)}</option>`).join("")}</select></label><label>${esc(t("incomeLimit"))}<input name="income_limit" type="number" min="0" step="1" value="${esc(row.income_limit ?? "")}"></label><label>${esc(t("minimumMarks"))}<input name="minimum_marks" type="number" min="0" max="100" step="0.1" value="${esc(row.minimum_marks ?? "")}"></label><label>${esc(t("disabilityRequirement"))}<select name="disability_required"><option value="false" ${!row.disability_required ? "selected" : ""}>${esc(t("noRequirement"))}</option><option value="true" ${row.disability_required ? "selected" : ""}>${esc(t("yesNo")[0])}</option></select></label><label>${esc(t("deadlineField"))}<input name="deadline" type="date" value="${esc(row.deadline || "")}"></label><label>${esc(t("idType"))}<select name="id_type"><option value="sats" ${row.id_type !== "ssp" ? "selected" : ""}>${esc(t("sats"))}</option><option value="ssp" ${row.id_type === "ssp" ? "selected" : ""}>${esc(t("ssp"))}</option></select></label><label>${esc(t("lastVerified"))}<input name="last_verified" type="date" value="${esc(row.last_verified || "")}"></label><label class="wide">${esc(t("benefitEn"))}<input name="benefit_en" required value="${esc(row.benefit_en || "")}"></label><label class="wide">${esc(t("benefitKn"))}<input name="benefit_kn" required value="${esc(row.benefit_kn || "")}"></label><label class="wide">${esc(t("rulesEn"))}<textarea name="eligibility_en">${esc(row.eligibility_text?.en || "")}</textarea></label><label class="wide">${esc(t("rulesKn"))}<textarea name="eligibility_kn">${esc(row.eligibility_text?.kn || "")}</textarea></label><label class="wide">${esc(t("documentsEn"))}<textarea name="documents_en">${esc((row.documents_required?.en || []).join("\n"))}</textarea></label><label class="wide">${esc(t("documentsKn"))}<textarea name="documents_kn">${esc((row.documents_required?.kn || []).join("\n"))}</textarea></label><label class="wide">${esc(t("stepsEn"))}<textarea name="steps_en">${esc((row.apply_steps?.en || []).join("\n"))}</textarea></label><label class="wide">${esc(t("stepsKn"))}<textarea name="steps_kn">${esc((row.apply_steps?.kn || []).join("\n"))}</textarea></label><label class="wide">${esc(t("officialLink"))}<input name="application_url" type="url" value="${esc(row.application_url || "")}"></label><label class="wide">${esc(t("dataSource"))}<input name="data_source" required value="${esc(row.data_source || "")}"></label></div><p class="form-message" role="status"></p><div class="form-actions"><button class="button button-primary" type="submit">${esc(t("save"))}</button><button class="button button-outline" type="button" onclick="this.closest('form').remove()">${esc(t("cancel"))}</button>${id ? `<button class="danger-link" type="button" onclick="deleteScheme('${esc(id)}')">${esc(t("delete"))}</button>` : ""}</div></form>`;
  panel.scrollIntoView({ behavior: "smooth", block: "start" });
}

function lines(value) { return value.split("\n").map(line => line.trim()).filter(Boolean); }
async function saveScheme(event, id) {
  event.preventDefault(); const form = event.currentTarget; const data = new FormData(form); const emptyNull = value => value === "" ? null : Number(value);
  const payload = { name_en: data.get("name_en"), name_kn: data.get("name_kn"), type: data.get("type"), class_min: Number(data.get("class_min")), class_max: Number(data.get("class_max")), categories: data.getAll("categories"), gender_restriction: data.get("gender_restriction"), income_limit: emptyNull(data.get("income_limit")), minimum_marks: emptyNull(data.get("minimum_marks")), disability_required: data.get("disability_required") === "true", deadline: data.get("deadline") || null, last_verified: data.get("last_verified") || null, benefit_en: data.get("benefit_en"), benefit_kn: data.get("benefit_kn"), eligibility_text: { en: data.get("eligibility_en"), kn: data.get("eligibility_kn") }, documents_required: { en: lines(data.get("documents_en")), kn: lines(data.get("documents_kn")) }, apply_steps: { en: lines(data.get("steps_en")), kn: lines(data.get("steps_kn")) }, id_type: data.get("id_type"), application_url: data.get("application_url") || null, data_source: data.get("data_source"), status: data.get("status"), updated_by: state.user.user.id };
  const message = form.querySelector(".form-message");
  try { await api(`/rest/v1/schemes${id ? `?id=eq.${encodeURIComponent(id)}` : ""}`, { method: id ? "PATCH" : "POST", headers: { Prefer: "return=representation" }, body: JSON.stringify(payload) }, true); await loadSchemes(); render(); toast(t("saveSuccess")); }
  catch { message.textContent = t("saveError"); }
}
async function deleteScheme(id) { if (!confirm(t("confirmDelete"))) return; try { await api(`/rest/v1/schemes?id=eq.${encodeURIComponent(id)}`, { method: "DELETE" }, true); await loadSchemes(); render(); } catch { toast(t("saveError")); } }

function announcementsContent() { return `<form class="announcement-form" onsubmit="saveAnnouncement(event)"><label>${esc(t("announcementEn"))}<textarea name="message_en" maxlength="240">${esc(state.announcement?.message_en || "")}</textarea></label><label>${esc(t("announcementKn"))}<textarea name="message_kn" maxlength="240">${esc(state.announcement?.message_kn || "")}</textarea></label><p class="form-message" role="status"></p><div class="form-actions"><button class="button button-primary">${esc(t("setAnnouncement"))}</button><button class="button button-outline" type="button" onclick="clearAnnouncement()">${esc(t("clearAnnouncement"))}</button></div></form>`; }
async function saveAnnouncement(event) { event.preventDefault(); const form = event.currentTarget; const data = new FormData(form); try { const body = { id: true, message_en: data.get("message_en").trim() || null, message_kn: data.get("message_kn").trim() || null, updated_by: state.user.user.id }; await api("/rest/v1/announcements?id=eq.true", { method: "PATCH", headers: { Prefer: "return=representation" }, body: JSON.stringify(body) }, true); state.announcement = body.message_en || body.message_kn ? body : null; render(); toast(t("announcementSaved")); } catch { form.querySelector(".form-message").textContent = t("saveError"); } }
async function clearAnnouncement() { try { await api("/rest/v1/announcements?id=eq.true", { method: "PATCH", body: JSON.stringify({ message_en: null, message_kn: null, updated_by: state.user.user.id }) }, true); state.announcement = null; render(); } catch { toast(t("saveError")); } }

async function loadStaff() { const [staff, activity] = await Promise.all([api("/rest/v1/staff_profiles?select=user_id,email,role,enabled,must_change_password&order=email.asc", {}, true), api("/rest/v1/activity_log?select=id,action,scheme_name_en,created_at,staff_profiles(email)&order=created_at.desc&limit=30", {}, true)]); state.staffList = staff || []; state.activity = activity || []; }
function staffContent() { return `<section class="staff-section"><h2>${esc(t("addStaff"))}</h2><form class="staff-create-form" onsubmit="createStaff(event)"><label>${esc(t("staffEmail"))}<input name="email" type="email" required></label><label>${esc(t("staffPassword"))}<input name="password" type="password" minlength="12" required></label><label>${esc(t("role"))}<select name="role"><option value="editor">${esc(t("editor"))}</option><option value="admin">${esc(t("admin"))}</option></select></label><button class="button button-primary">${esc(t("addStaff"))}</button><p class="form-message" role="status"></p></form></section><section class="staff-section"><h2>${esc(t("staffAccounts"))}</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>${esc(t("email"))}</th><th>${esc(t("role"))}</th><th>${esc(t("enabled"))}</th><th></th></tr></thead><tbody>${state.staffList.map(row => `<tr><td>${esc(row.email || "")}</td><td>${esc(t(row.role))}</td><td>${esc(t(row.enabled ? "enabled" : "disabled"))}</td><td><button class="text-arrow" onclick="toggleStaff('${esc(row.user_id)}',${!row.enabled})">${esc(t(row.enabled ? "disable" : "enable"))}</button></td></tr>`).join("")}</tbody></table></div></section><section class="staff-section"><h2>${esc(t("activity"))}</h2>${state.activity.length ? `<ul class="activity-list">${state.activity.map(row => `<li><span><strong>${esc(row.staff_profiles?.email || "Staff")}</strong> ${esc(t(row.action))} <strong>${esc(row.scheme_name_en || "")}</strong></span><time>${esc(dateText(row.created_at?.slice(0, 10)))}</time></li>`).join("")}</ul>` : `<p>${esc(t("noActivity"))}</p>`}</section>`; }
async function staffFunction(payload) { return api("/functions/v1/manage-staff", { method: "POST", body: JSON.stringify(payload) }, true); }
async function createStaff(event) { event.preventDefault(); const form = event.currentTarget; const data = new FormData(form); try { await staffFunction({ action: "create", email: data.get("email"), password: data.get("password"), role: data.get("role") }); await loadStaff(); render(); toast(t("staffCreated")); } catch { form.querySelector(".form-message").textContent = t("staffError"); } }
async function toggleStaff(id, enabled) { try { await staffFunction({ action: "set_enabled", user_id: id, enabled }); await loadStaff(); render(); } catch { toast(t("staffError")); } }

function toast(message) { state.toast = message; render(); window.setTimeout(() => { state.toast = ""; render(); }, 2600); }
function render() {
  const pages = { home: homePage, checker: checkerPage, results: resultsPage, detail: detailPage, help: helpPage, about: aboutPage, login: loginPage };
  let content = pages[state.route] ? pages[state.route]() : "";
  if (["dashboard", "schemes", "announcements", "staff"].includes(state.route)) { const body = state.route === "dashboard" ? dashboardContent() : state.route === "schemes" ? schemeListPage() : state.route === "announcements" ? announcementsContent() : staffContent(); content = staffShell(body); }
  root.innerHTML = `${header()}${content}${state.toast ? `<div class="toast" role="status">${esc(state.toast)}</div>` : ""}`;
  document.documentElement.lang = state.lang;
  document.title = state.route === "help" ? `${t("helpTitle")} · KSEP (Karnataka Scholarship Eligibility Portal)` : "KSEP (Karnataka Scholarship Eligibility Portal)";
}

function toggleLanguage() { state.lang = state.lang === "kn" ? "en" : "kn"; localStorage.setItem("sf-language", state.lang); render(); }
function toggleMenu() { state.menuOpen = !state.menuOpen; render(); }
function togglePrinciple(index) { state.principleOpen = state.principleOpen === index ? -1 : index; render(); }
function selectAnswer(key, value) { state.answers[key] = value; render(); }
function previousQuestion() { if (state.step > 0) state.step -= 1; render(); }
function nextQuestion() { if (state.answers[questionKeys[state.step]] === undefined) return; if (state.step < questionKeys.length - 1) { state.step += 1; render(); } else finishChecker(); }
function shareResults() { const names = ["likely", "maybe", "almost"].flatMap(group => state.results[group].map(item => localized(item.scheme, "name"))); const text = names.length ? `${t("resultsTitle")}: ${names.join(", ")}. ${t("disclaimerShort")}` : `${t("zeroTitle")}. ${t("zeroText")}`; window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, "_blank", "noopener,noreferrer"); }
function searchSchemes(value) { state.search = value; const input = document.activeElement; const start = input?.selectionStart; render(); const next = document.querySelector(".search-field input"); next?.focus(); if (start != null) next?.setSelectionRange(start, start); }

async function submitLogin(event) {
  event.preventDefault(); const now = Date.now(); const message = document.querySelector("#auth-message");
  if (now < loginLockedUntil) { message.textContent = t("loginError"); return; }
  const data = new FormData(event.currentTarget);
  try {
    const session = await api("/auth/v1/token?grant_type=password", { method: "POST", body: JSON.stringify({ email: data.get("email"), password: data.get("password") }) });
    state.user = session;
    const profiles = await api(`/rest/v1/staff_profiles?user_id=eq.${encodeURIComponent(session.user.id)}&select=*&limit=1`, {}, true);
    state.profile = profiles?.[0] || null;
    if (!state.profile?.enabled) throw new Error("disabled");
    sessionStorage.setItem("sf-staff-session", JSON.stringify(session));
    loginFailures = 0; nav("login");
  } catch {
    loginFailures += 1;
    if (loginFailures >= 5) { loginLockedUntil = Date.now() + Math.min(15, loginFailures - 3) * 60000; }
    message.textContent = t("loginError");
  }
}
async function submitPasswordChange(event) { event.preventDefault(); const message = document.querySelector("#auth-message"); const password = new FormData(event.currentTarget).get("password"); try { await api("/auth/v1/user", { method: "PUT", body: JSON.stringify({ password }) }, true); await api(`/rest/v1/staff_profiles?user_id=eq.${encodeURIComponent(state.user.user.id)}`, { method: "PATCH", body: JSON.stringify({ must_change_password: false }) }, true); state.profile.must_change_password = false; nav("login"); } catch { message.textContent = t("saveError"); } }
function signOut() { state.user = null; state.profile = null; sessionStorage.removeItem("sf-staff-session"); state.dashboard = null; state.staffList = []; nav("home"); }
async function restoreSession() { const saved = sessionStorage.getItem("sf-staff-session"); if (!saved || !HAS_BACKEND) return; try { let session = JSON.parse(saved); if (session.expires_at && session.expires_at * 1000 < Date.now() + 30000) { session = await api("/auth/v1/token?grant_type=refresh_token", { method: "POST", body: JSON.stringify({ refresh_token: session.refresh_token }) }); sessionStorage.setItem("sf-staff-session", JSON.stringify(session)); } state.user = session; const rows = await api(`/rest/v1/staff_profiles?user_id=eq.${encodeURIComponent(session.user.id)}&select=*&limit=1`, {}, true); state.profile = rows?.[0] || null; if (!state.profile?.enabled) signOut(); } catch { sessionStorage.removeItem("sf-staff-session"); } }
async function loadStaffRoute() { if (!state.user || state.profile?.must_change_password) return; try { if (state.route === "dashboard") await loadDashboard(); if (state.route === "schemes") await loadSchemes(); if (state.route === "announcements") { const rows = await api("/rest/v1/announcements?select=*&limit=1", {}, true); state.announcement = rows?.[0]?.message_en || rows?.[0]?.message_kn ? rows[0] : null; } if (state.route === "staff" && state.profile.role === "admin") await loadStaff(); } catch { state.dashboard = null; } }

window.toggleLanguage = toggleLanguage; window.toggleMenu = toggleMenu; window.togglePrinciple = togglePrinciple; window.startChecker = startChecker; window.selectAnswer = selectAnswer; window.previousQuestion = previousQuestion; window.nextQuestion = nextQuestion; window.nav = nav; window.openDetail = openDetail; window.shareResults = shareResults; window.submitLogin = submitLogin; window.submitPasswordChange = submitPasswordChange; window.signOut = signOut; window.editScheme = editScheme; window.saveScheme = saveScheme; window.deleteScheme = deleteScheme; window.searchSchemes = searchSchemes; window.saveAnnouncement = saveAnnouncement; window.clearAnnouncement = clearAnnouncement; window.createStaff = createStaff; window.toggleStaff = toggleStaff;

window.addEventListener("hashchange", async () => { routeToHash(); if (["dashboard", "schemes", "announcements", "staff"].includes(state.route)) await loadStaffRoute(); render(); });
window.addEventListener("keydown", event => { if (event.key === "Escape" && state.menuOpen) { state.menuOpen = false; render(); } });
(async function init() { routeToHash(); await Promise.all([loadPublicData(), restoreSession()]); if (["dashboard", "schemes", "announcements", "staff"].includes(state.route)) await loadStaffRoute(); render(); })();